  "quiz.generate_and_start": { en: "Generate & Start", te: "రూపొందించి ప్రారంభించండి", hi: "बनाएं और शुरू करें", ta: "உருவாக்கி தொடங்கு", kn: "ರಚಿಸಿ ಪ್ರಾರಂಭಿಸಿ", bn: "তৈরি করে শুরু করুন", mr: "तयार करा व सुरू करा" },

