  "pronunciation.mic_unsupported": { en: "Speech recognition is not supported in this browser. You can still listen to native audio models.", te: "ఈ బ్రౌజర్‌లో స్పీచ్ రికగ్నిషన్ మద్దతు లేదు. మీరు ఇప్పటికీ స్థానిక ఆడియో మోడల్స్ వినవచ్చు.", hi: "इस ब्राउज़र में स्पीच रिकग्निशन समर्थित नहीं है। आप फिर भी देशी ऑडियो मॉडल सुन सकते हैं।", ta: "இந்த உலாவியில் பேச்சு அங்கீகாரம் ஆதரிக்கப்படவில்லை. நீங்கள் இன்னும் நேட்டிவ் ஆடியோவைக் கேட்கலாம்.", kn: "ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಧ್ವನಿ ಗುರುತಿಸುವಿಕೆ ಬೆಂಬಲಿತವಿಲ್ಲ. ನೀವು ಇನ್ನೂ ಸ್ಥಳೀಯ ಆಡಿಯೊ ಮಾದರಿಗಳನ್ನು ಕೇಳಬಹುದು.", bn: "এই ব্রাউজারে স্পিচ রিকগনিশন সমর্থিত নয়। আপনি এখনও স্থানীয় অডিও মডেল শুনতে পারেন।", mr: "या ब्राउझरमध्ये स्पीच रेकग्निशन समर्थित नाही. तुम्ही तरीही मूळ ऑडिओ मॉडेल ऐकू शकता." },
  "pronunciation.studio_title": { en: "AI Pronunciation & Speech Studio", te: "AI ఉచ్ఛారణ & స్పీచ్ స్టూడియో", hi: "AI उच्चारण और स्पीच स्टूडियो", ta: "AI உச்சரிப்பு & பேச்சு ஸ்டூடியோ", kn: "AI ಉಚ್ಚಾರಣೆ ಮತ್ತು ಭಾಷಣ ಸ್ಟುಡಿಯೋ", bn: "AI উচ্চারণ ও স্পিচ স্টুডিও", mr: "AI उच्चार व स्पीच स्टुडिओ" },
  "pronunciation.voice_coach_badge": { en: "Voice & Phonetics Coach", te: "వాయిస్ & ధ్వని శాస్త్ర కోచ్", hi: "वॉइस और फोनेटिक्स कोच", ta: "குரல் & ஒலியியல் பயிற்சியாளர்", kn: "ಧ್ವನಿ ಮತ್ತು ಧ್ವನಿಶಾಸ್ತ್ರ ತರಬೇತುದಾರ", bn: "ভয়েস ও ধ্বনিবিদ্যা কোচ", mr: "आवाज व ध्वनिशास्त्र प्रशिक्षक" },
  "pronunciation.studio_subtitle": { en: "Analyze syllable stress, phonetic clarity, intonation contours, and overcome native accent friction.", te: "అక్షర ఒత్తిడి, ధ్వని స్పష్టత, స్వర హెచ్చుతగ్గులను విశ్లేషించి, స్థానిక యాస ఇబ్బందులను అధిగమించండి.", hi: "अक्षर तनाव, ध्वन्यात्मक स्पष्टता, स्वर विन्यास का विश्लेषण करें और देशी उच्चारण की बाधाओं को दूर करें।", ta: "எழுத்தழுத்தம், ஒலி தெளிவு, தொனி வளைவுகளை பகுப்பாய்வு செய்து, நேட்டிவ் உச்சரிப்பு தடைகளை சமாளிக்கவும்.", kn: "ಉಚ್ಚಾರಾಂಶ ಒತ್ತಡ, ಧ್ವನಿ ಸ್ಪಷ್ಟತೆ, ಸ್ವರ ಏರಿಳಿತಗಳನ್ನು ವಿಶ್ಲೇಷಿಸಿ ಸ್ಥಳೀಯ ಉಚ್ಚಾರಣಾ ಅಡೆತಡೆಗಳನ್ನು ಮೀರಿ.", bn: "শব্দাংশ চাপ, ধ্বনিগত স্বচ্ছতা, স্বরভঙ্গি বিশ্লেষণ করুন এবং স্থানীয় উচ্চারণের বাধা কাটিয়ে উঠুন।", mr: "अक्षर ताण, ध्वनी स्पष्टता, स्वर आरोहावरोह यांचे विश्लेषण करा व मूळ उच्चार अडथळे दूर करा." },
