  "pronunciation.enter_sentence_label": { en: "Enter any sentence to practice pronunciation:", te: "ఉచ్ఛారణ అభ్యాసానికి ఏదైనా వాక్యాన్ని నమోదు చేయండి:", hi: "उच्चारण अभ्यास के लिए कोई भी वाक्य दर्ज करें:", ta: "உச்சரிப்பு பயிற்சிக்கு ஏதேனும் வாக்கியத்தை உள்ளிடவும்:", kn: "ಉಚ್ಚಾರಣಾ ಅಭ್ಯಾಸಕ್ಕಾಗಿ ಯಾವುದೇ ವಾಕ್ಯವನ್ನು ನಮೂದಿಸಿ:", bn: "উচ্চারণ অনুশীলনের জন্য যেকোনো বাক্য লিখুন:", mr: "उच्चार सरावासाठी कोणतेही वाक्य टाका:" },
  "pronunciation.type_sentence_placeholder": { en: "Type your sentence here...", te: "మీ వాక్యాన్ని ఇక్కడ టైప్ చేయండి...", hi: "अपना वाक्य यहाँ टाइप करें...", ta: "உங்கள் வாக்கியத்தை இங்கே தட்டச்சு செய்யவும்...", kn: "ನಿಮ್ಮ ವಾಕ್ಯವನ್ನು ಇಲ್ಲಿ ಟೈಪ್ ಮಾಡಿ...", bn: "আপনার বাক্য এখানে টাইপ করুন...", mr: "तुमचे वाक्य इथे टाइप करा..." },
  "pronunciation.stop_and_analyze": { en: "Stop Recording & Analyze", te: "రికార్డింగ్ ఆపి విశ్లేషించండి", hi: "रिकॉर्डिंग रोकें और विश्लेषण करें", ta: "பதிவை நிறுத்தி பகுப்பாய்வு செய்யவும்", kn: "ರೆಕಾರ್ಡಿಂಗ್ ನಿಲ್ಲಿಸಿ ವಿಶ್ಲೇಷಿಸಿ", bn: "রেকর্ডিং থামিয়ে বিশ্লেষণ করুন", mr: "रेकॉर्डिंग थांबवा व विश्लेषण करा" },
  "pronunciation.record_and_evaluate": { en: "Record & Evaluate Speaking", te: "మాట్లాడటాన్ని రికార్డ్ చేసి మూల్యాంకనం చేయండి", hi: "बोलना रिकॉर्ड करें और मूल्यांकन करें", ta: "பேச்சைப் பதிவு செய்து மதிப்பிடவும்", kn: "ಮಾತನಾಡುವುದನ್ನು ರೆಕಾರ್ಡ್ ಮಾಡಿ ಮೌಲ್ಯಮಾಪನ ಮಾಡಿ", bn: "কথা রেকর্ড করে মূল্যায়ন করুন", mr: "बोलणे रेकॉर्ड करा व मूल्यमापन करा" },
  "pronunciation.live_speech_captured": { en: "Live Speech Captured:", te: "ప్రత్యక్ష మాటలు క్యాప్చర్ చేయబడ్డాయి:", hi: "लाइव स्पीच कैप्चर की गई:", ta: "நேரடி பேச்சு பதிவு செய்யப்பட்டது:", kn: "ಲೈವ್ ಮಾತು ಸೆರೆಹಿಡಿಯಲಾಗಿದೆ:", bn: "লাইভ কথা ধারণ করা হয়েছে:", mr: "थेट बोलणे रेकॉर्ड झाले:" },
  "pronunciation.analyzing": { en: "Analyzing Syllable Stress & Articulation...", te: "అక్షర ఒత్తిడి & ఉచ్ఛారణను విశ్లేషిస్తోంది...", hi: "अक्षर तनाव और उच्चारण का विश्लेषण किया जा रहा है...", ta: "எழுத்தழுத்தம் & உச்சரிப்பு பகுப்பாய்வு செய்யப்படுகிறது...", kn: "ಉಚ್ಚಾರಾಂಶ ಒತ್ತಡ ಮತ್ತು ಉಚ್ಚಾರಣೆಯನ್ನು ವಿಶ್ಲೇಷಿಸಲಾಗುತ್ತಿದೆ...", bn: "শব্দাংশ চাপ ও উচ্চারণ বিশ্লেষণ করা হচ্ছে...", mr: "अक्षर ताण व उच्चाराचे विश्लेषण होत आहे..." },
  "pronunciation.analyzing_desc": { en: "Comparing your voice recording against phonemic benchmarks and acoustic clarity models.", te: "మీ వాయిస్ రికార్డింగ్‌ను ధ్వని ప్రమాణాలు మరియు అకౌస్టిక్ స్పష్టత మోడల్స్‌తో పోల్చుతోంది.", hi: "आपकी वॉइस रिकॉर्डिंग की तुलना ध्वन्यात्मक मानकों और ध्वनिक स्पष्टता मॉडल से की जा रही है।", ta: "உங்கள் குரல் பதிவை ஒலியியல் தரநிலைகள் மற்றும் ஒலி தெளிவு மாதிரிகளுடன் ஒப்பிடுகிறது.", kn: "ನಿಮ್ಮ ಧ್ವನಿ ರೆಕಾರ್ಡಿಂಗ್ ಅನ್ನು ಧ್ವನಿಮಾ ಮಾನದಂಡಗಳು ಮತ್ತು ಅಕೌಸ್ಟಿಕ್ ಸ್ಪಷ್ಟತೆ ಮಾದರಿಗಳೊಂದಿಗೆ ಹೋಲಿಸಲಾಗುತ್ತಿದೆ.", bn: "আপনার ভয়েস রেকর্ডিং ধ্বনিগত মানদণ্ড ও শাব্দ স্বচ্ছতা মডেলের সাথে তুলনা করা হচ্ছে।", mr: "तुमचे आवाज रेकॉर्डिंग ध्वनिशास्त्रीय मानके व ध्वनि स्पष्टता मॉडेलशी तुलना केली जात आहे." },
  "pronunciation.acoustic_analysis_results": { en: "Acoustic Analysis Results", te: "అకౌస్టిక్ విశ్లేషణ ఫలితాలు", hi: "ध्वनिक विश्लेषण परिणाम", ta: "ஒலி பகுப்பாய்வு முடிவுகள்", kn: "ಅಕೌಸ್ಟಿಕ್ ವಿಶ್ಲೇಷಣಾ ಫಲಿತಾಂಶಗಳು", bn: "শাব্দ বিশ্লেষণ ফলাফল", mr: "ध्वनिक विश्लेषण निकाल" },
