  "pronunciation.acoustic_score": { en: "Acoustic Score", te: "అకౌస్టిక్ స్కోరు", hi: "ध्वनिक स्कोर", ta: "ஒலி மதிப்பெண்", kn: "ಅಕೌಸ್ಟಿಕ್ ಅಂಕ", bn: "শাব্দ স্কোর", mr: "ध्वनिक गुण" },
  "pronunciation.word_breakdown_label": { en: "Word-by-Word Articulation Breakdown:", te: "పద-వారీ ఉచ్ఛారణ విభజన:", hi: "शब्द-दर-शब्द उच्चारण विश्लेषण:", ta: "சொல் வாரியான உச்சரிப்பு பகுப்பாய்வு:", kn: "ಪದ-ಪದದ ಉಚ್ಚಾರಣಾ ವಿಭಜನೆ:", bn: "শব্দ-অনুযায়ী উচ্চারণ বিশ্লেষণ:", mr: "शब्दानुसार उच्चार विभाजन:" },
