  "stress.pitch_intonation_title": { en: "Pitch & Intonation Contour", te: "పిచ్ & స్వర హెచ్చుతగ్గుల వక్రత", hi: "पिच और स्वर विन्यास वक्र", ta: "சுருதி & தொனி வளைவு", kn: "ಪಿಚ್ ಮತ್ತು ಸ್ವರ ಏರಿಳಿತ ವಕ್ರರೇಖೆ", bn: "পিচ ও স্বরভঙ্গি বক্ররেখা", mr: "पिच व स्वर चढउतार वक्र" },
