  "stress.next_crisis_challenge": { en: "Next Crisis Challenge", te: "తదుపరి సంక్షోభ సవాలు", hi: "अगली संकट चुनौती", ta: "அடுத்த நெருக்கடி சவால்", kn: "ಮುಂದಿನ ಬಿಕ್ಕಟ್ಟು ಸವಾಲು", bn: "পরবর্তী সংকট চ্যালেঞ্জ", mr: "पुढील संकट आव्हान" },
  "stress.generate_custom_crisis_title": { en: "Generate Custom High-Stress Crisis", te: "అనుకూల అధిక-ఒత్తిడి సంక్షోభాన్ని రూపొందించండి", hi: "कस्टम उच्च-तनाव संकट बनाएं", ta: "தனிப்பயன் அதிக-அழுத்த நெருக்கடியை உருவாக்கு", kn: "ಕಸ್ಟಮ್ ಹೆಚ್ಚಿನ-ಒತ್ತಡದ ಬಿಕ್ಕಟ್ಟನ್ನು ರಚಿಸಿ", bn: "কাস্টম উচ্চ-চাপ সংকট তৈরি করুন", mr: "सानुकूल उच्च-ताण संकट तयार करा" },
  "stress.generate_custom_crisis_desc": { en: "Describe any high-pressure situation you want to conquer (e.g. salary negotiation with strict CEO, medical emergency abroad, product recall, hostile press question).", te: "మీరు అధిగమించాలనుకుంటున్న ఏదైనా అధిక-ఒత్తిడి పరిస్థితిని వివరించండి (ఉదా. కఠినమైన CEOతో జీతం చర్చ, విదేశాలలో వైద్య అత్యవసరం, ఉత్పత్తి రీకాల్, శత్రు పత్రికా ప్రశ్న).", hi: "किसी भी उच्च-दबाव स्थिति का वर्णन करें जिसे आप जीतना चाहते हैं (जैसे सख्त CEO के साथ वेतन बातचीत, विदेश में चिकित्सा आपातकाल, उत्पाद वापसी, शत्रुतापूर्ण प्रेस प्रश्न)।", ta: "நீங்கள் வெல்ல விரும்பும் எந்த உயர்-அழுத்த சூழ்நிலையையும் விவரிக்கவும் (எ.கா. கண்டிப்பான CEO உடன் சம்பள பேச்சுவார்த்தை, வெளிநாட்டில் மருத்துவ அவசரநிலை, தயாரிப்பு திரும்பப் பெறல், விரோத பத்திரிகை கேள்வி).", kn: "ನೀವು ಜಯಿಸಲು ಬಯಸುವ ಯಾವುದೇ ಹೆಚ್ಚಿನ-ಒತ್ತಡದ ಸನ್ನಿವೇಶವನ್ನು ವಿವರಿಸಿ (ಉದಾ. ಕಠಿಣ CEO ಜೊತೆ ವೇತನ ಮಾತುಕತೆ, ವಿದೇಶದಲ್ಲಿ ವೈದ್ಯಕೀಯ ತುರ್ತುಸ್ಥಿತಿ, ಉತ್ಪನ್ನ ಹಿಂತೆಗೆತ, ಪ್ರತಿಕೂಲ ಪತ್ರಿಕಾ ಪ್ರಶ್ನೆ).", bn: "আপনি জয় করতে চান এমন যেকোনো উচ্চ-চাপ পরিস্থিতি বর্ণনা করুন (যেমন কঠোর CEO-র সাথে বেতন আলোচনা, বিদেশে চিকিৎসা জরুরি অবস্থা, পণ্য প্রত্যাহার, প্রতিকূল সংবাদমাধ্যম প্রশ্ন)।", mr: "तुम्हाला जिंकायच्या कोणत्याही उच्च-दबाव परिस्थितीचे वर्णन करा (उदा. कडक CEO सोबत पगार वाटाघाटी, परदेशात वैद्यकीय आणीबाणी, उत्पादन परत मागवणे, प्रतिकूल पत्रकार प्रश्न)." },
