  "fluency.architecture_badge": { en: "REAL-WORLD FLUENCY ARCHITECTURE", te: "వాస్తవ-ప్రపంచ ధారాళత నిర్మాణం", hi: "वास्तविक-विश्व प्रवाह वास्तुकला", ta: "நிஜ-உலக சரள கட்டமைப்பு", kn: "ನೈಜ-ಜಗತ್ತಿನ ನಿರರ್ಗಳತೆ ವಾಸ್ತುಶಿಲ್ಪ", bn: "বাস্তব-বিশ্ব সাবলীলতা স্থাপত্য", mr: "वास्तविक-जगातील अस्खलितता रचना" },
  "fluency.differentiators_count": { en: "6 Core Structural Market Differentiators", te: "6 ప్రధాన నిర్మాణాత్మక మార్కెట్ విభిన్నతలు", hi: "6 प्रमुख संरचनात्मक बाज़ार भिन्नताएँ", ta: "6 முக்கிய கட்டமைப்பு சந்தை வேறுபாடுகள்", kn: "6 ಪ್ರಮುಖ ರಚನಾತ್ಮಕ ಮಾರುಕಟ್ಟೆ ವ್ಯತ್ಯಾಸಗಳು", bn: "৬টি মূল কাঠামোগত বাজার পার্থক্যকারী", mr: "6 मुख्य संरचनात्मक बाजार फरक" },
  "fluency.hero_title": { en: "Bridging Guided Practice to Real-World Spoken Fluency", te: "మార్గదర్శక అభ్యాసాన్ని వాస్తవ-ప్రపంచ మాట్లాడే ధారాళతకు అనుసంధానించడం", hi: "निर्देशित अभ्यास को वास्तविक-विश्व बोली प्रवाह से जोड़ना", ta: "வழிகாட்டப்பட்ட பயிற்சியை நிஜ-உலக பேச்சு சரளத்துடன் இணைத்தல்", kn: "ಮಾರ್ಗದರ್ಶಿತ ಅಭ್ಯಾಸವನ್ನು ನೈಜ-ಜಗತ್ತಿನ ಮಾತನಾಡುವ ನಿರರ್ಗಳತೆಗೆ ಸಂಪರ್ಕಿಸುವುದು", bn: "নির্দেশিত অনুশীলনকে বাস্তব-বিশ্ব কথ্য সাবলীলতার সাথে সংযুক্ত করা", mr: "मार्गदर्शित सरावाला वास्तविक-जगातील बोलण्याच्या अस्खलिततेशी जोडणे" },
  "fluency.hero_desc": { en: "Most language apps treat mistakes as isolated events, provide binary right/wrong scores, and ignore pragmatic register. Fluenxia introduces dynamic error memory re-testing, deep acoustic prosody modeling, cultural register calibration, high-stakes domain friction, and post-session After-Action Audits.", te: "చాలా భాషా యాప్‌లు తప్పులను ఒంటరి సంఘటనలుగా పరిగణించి, బైనరీ సరైన/తప్పు స్కోర్‌లను ఇచ్చి, ప్రయోజనాత్మక రిజిస్టర్‌ను విస్మరిస్తాయి. Fluenxia డైనమిక్ ఎర్రర్ మెమరీ రీ-టెస్టింగ్, లోతైన అకౌస్టిక్ ప్రొసొడీ మోడలింగ్, సాంస్కృతిక రిజిస్టర్ కాలిబ్రేషన్, అధిక-పణం డొమైన్ ఘర్షణ మరియు సెషన్ అనంతర ఆఫ్టర్-యాక్షన్ ఆడిట్‌లను పరిచయం చేస్తుంది.", hi: "अधिकांश भाषा ऐप्स गलतियों को अलग-थलग घटनाओं के रूप में मानते हैं, केवल सही/गलत स्कोर देते हैं, और व्यावहारिक रजिस्टर को नज़रअंदाज़ करते हैं। Fluenxia गतिशील त्रुटि स्मृति पुनः-परीक्षण, गहन ध्वनिक प्रोसोडी मॉडलिंग, सांस्कृतिक रजिस्टर अंशांकन, उच्च-दांव डोमेन घर्षण, और सत्र-पश्चात के बाद-कार्य ऑडिट प्रस्तुत करता है।", ta: "பெரும்பாலான மொழி பயன்பாடுகள் தவறுகளை தனித்த நிகழ்வுகளாகக் கருதி, சரி/தவறு மதிப்பெண்களை மட்டும் அளித்து, நடைமுறை பதிவை புறக்கணிக்கின்றன. Fluenxia மாறும் தவறு நினைவக மறுசோதனை, ஆழமான ஒலி தாள மாதிரியாக்கம், கலாச்சார பதிவு அளவீடு, உயர்-பங்கய களப் போராட்டம் மற்றும் அமர்வுக்குப் பிந்தைய செயல்பாட்டு தணிக்கைகளை அறிமுகப்படுத்துகிறது.", kn: "ಹೆಚ್ಚಿನ ಭಾಷಾ ಅಪ್ಲಿಕೇಶನ್‌ಗಳು ತಪ್ಪುಗಳನ್ನು ಪ್ರತ್ಯೇಕ ಘಟನೆಗಳಂತೆ ಪರಿಗಣಿಸಿ, ಬೈನರಿ ಸರಿ/ತಪ್ಪು ಅಂಕಗಳನ್ನು ನೀಡಿ, ಪ್ರಾಯೋಗಿಕ ರಿಜಿಸ್ಟರ್ ಅನ್ನು ನಿರ್ಲಕ್ಷಿಸುತ್ತವೆ. Fluenxia ಕ್ರಿಯಾತ್ಮಕ ದೋಷ ಸ್ಮರಣೆ ಮರುಪರೀಕ್ಷೆ, ಆಳವಾದ ಅಕೌಸ್ಟಿಕ್ ಪ್ರಾಸೋಡಿ ಮಾಡೆಲಿಂಗ್, ಸಾಂಸ್ಕೃತಿಕ ರಿಜಿಸ್ಟರ್ ಕ್ಯಾಲಿಬ್ರೇಶನ್, ಉನ್ನತ-ಪಣ ಡೊಮೇನ್ ಘರ್ಷಣೆ ಮತ್ತು ಅಧಿವೇಶನದ ನಂತರದ ಕ್ರಿಯಾ-ಪರಿಶೀಲನೆಗಳನ್ನು ಪರಿಚಯಿಸುತ್ತದೆ.", bn: "বেশিরভাগ ভাষা অ্যাপ ভুলগুলোকে বিচ্ছিন্ন ঘটনা হিসেবে বিবেচনা করে, বাইনারি ঠিক/ভুল স্কোর দেয় এবং ব্যবহারিক রেজিস্টার উপেক্ষা করে। Fluenxia গতিশীল ত্রুটি স্মৃতি পুনঃপরীক্ষা, গভীর শাব্দ প্রোসোডি মডেলিং, সাংস্কৃতিক রেজিস্টার ক্যালিব্রেশন, উচ্চ-ঝুঁকির ডোমেইন ঘর্ষণ এবং সেশন-পরবর্তী আফটার-অ্যাকশন অডিট চালু করে।", mr: "बहुतांश भाषा अ‍ॅप्स चुकांना वेगळ्या घटना मानतात, फक्त बरोबर/चूक गुण देतात व व्यावहारिक रजिस्टर दुर्लक्षित करतात. Fluenxia गतिशील त्रुटी स्मृती पुनःचाचणी, सखोल ध्वनिक प्रोसोडी मॉडेलिंग, सांस्कृतिक रजिस्टर कॅलिब्रेशन, उच्च-पणाचे क्षेत्र घर्षण व सत्रानंतरचे आफ्टर-अ‍ॅक्शन ऑडिट सादर करते." },
