  "fluency.view_after_action_audit": { en: "View After-Action Audit", te: "ఆఫ్టర్-యాక్షన్ ఆడిట్‌ను వీక్షించండి", hi: "आफ्टर-एक्शन ऑडिट देखें", ta: "செயல்பாட்டு தணிக்கையைப் பார்க்கவும்", kn: "ಕ್ರಿಯಾ-ನಂತರದ ಲೆಕ್ಕಪರಿಶೋಧನೆ ವೀಕ್ಷಿಸಿ", bn: "আফটার-অ্যাকশন অডিট দেখুন", mr: "आफ्टर-अ‍ॅक्शन ऑडिट पहा" },
  "fluency.launch_studio": { en: "Launch Studio", te: "స్టూడియోను ప్రారంభించండి", hi: "स्टूडियो लॉन्च करें", ta: "ஸ்டூடியோவைத் தொடங்கு", kn: "ಸ್ಟುಡಿಯೋ ಪ್ರಾರಂಭಿಸಿ", bn: "স্টুডিও চালু করুন", mr: "स्टुडिओ सुरू करा" },

  // Grammar Doctor
  "doctor.title": { en: "AI Sentence & Grammar Doctor", te: "AI వాక్యం & వ్యాకరణ డాక్టర్", hi: "AI वाक्य और व्याकरण डॉक्टर", ta: "AI வாக்கியம் & இலக்கண மருத்துவர்", kn: "AI ವಾಕ್ಯ ಮತ್ತು ವ್ಯಾಕರಣ ವೈದ್ಯ", bn: "AI বাক্য ও ব্যাকরণ ডাক্তার", mr: "AI वाक्य व व्याकरण डॉक्टर" },
  "doctor.title_short": { en: "Sentence & Grammar Doctor", te: "వాక్యం & వ్యాకరణ డాక్టర్", hi: "वाक्य और व्याकरण डॉक्टर", ta: "வாக்கியம் & இலக்கண மருத்துவர்", kn: "ವಾಕ್ಯ ಮತ್ತು ವ್ಯಾಕರಣ ವೈದ್ಯ", bn: "বাক্য ও ব্যাকরণ ডাক্তার", mr: "वाक्य व व्याकरण डॉक्टर" },
  "doctor.subtitle": { en: "Type or paste any English sentence, paragraph, or question to unpack its grammar, parts of speech, and nuances.", te: "దాని వ్యాకరణం, పద భాగాలు మరియు సూక్ష్మభేదాలను విప్పడానికి ఏదైనా ఆంగ్ల వాక్యం, పేరా లేదా ప్రశ్నను టైప్ చేయండి లేదా పేస్ట్ చేయండి.", hi: "इसके व्याकरण, शब्द-भेद और बारीकियों को समझने के लिए कोई भी अंग्रेज़ी वाक्य, अनुच्छेद, या प्रश्न टाइप या पेस्ट करें।", ta: "இலக்கணம், சொல் வகைகள் மற்றும் நுணுக்கங்களை புரிந்துகொள்ள ஏதேனும் ஆங்கில வாக்கியம், பத்தி அல்லது கேள்வியை தட்டச்சு செய்யவும் அல்லது ஒட்டவும்.", kn: "ಅದರ ವ್ಯಾಕರಣ, ಪದ ಭಾಗಗಳು ಮತ್ತು ಸೂಕ್ಷ್ಮ ವ್ಯತ್ಯಾಸಗಳನ್ನು ಬಿಡಿಸಲು ಯಾವುದೇ ಇಂಗ್ಲಿಷ್ ವಾಕ್ಯ, ಪ್ಯಾರಾಗ್ರಾಫ್ ಅಥವಾ ಪ್ರಶ್ನೆಯನ್ನು ಟೈಪ್ ಮಾಡಿ ಅಥವಾ ಅಂಟಿಸಿ.", bn: "এর ব্যাকরণ, বাক্যাংশ ও সূক্ষ্মতা বোঝার জন্য যেকোনো ইংরেজি বাক্য, অনুচ্ছেদ বা প্রশ্ন টাইপ বা পেস্ট করুন।", mr: "त्याचे व्याकरण, शब्दभेद व सूक्ष्मता समजून घेण्यासाठी कोणतेही इंग्रजी वाक्य, परिच्छेद किंवा प्रश्न टाइप किंवा पेस्ट करा." },
  "doctor.input_placeholder": { en: "Enter any English sentence to analyze...", te: "విశ్లేషించడానికి ఏదైనా ఆంగ్ల వాక్యాన్ని నమోదు చేయండి...", hi: "विश्लेषण के लिए कोई भी अंग्रेज़ी वाक्य दर्ज करें...", ta: "பகுப்பாய்வு செய்ய ஏதேனும் ஆங்கில வாக்கியத்தை உள்ளிடவும்...", kn: "ವಿಶ್ಲೇಷಿಸಲು ಯಾವುದೇ ಇಂಗ್ಲಿಷ್ ವಾಕ್ಯವನ್ನು ನಮೂದಿಸಿ...", bn: "বিশ্লেষণের জন্য যেকোনো ইংরেজি বাক্য লিখুন...", mr: "विश्लेषणासाठी कोणतेही इंग्रजी वाक्य टाका..." },
  "doctor.try_samples": { en: "Try samples:", te: "నమూనాలను ప్రయత్నించండి:", hi: "नमूने आज़माएं:", ta: "மாதிரிகளை முயற்சிக்கவும்:", kn: "ಮಾದರಿಗಳನ್ನು ಪ್ರಯತ್ನಿಸಿ:", bn: "নমুনা চেষ্টা করুন:", mr: "नमुने वापरून पहा:" },
