  "dashboard.pillar_pronunciation_desc": { en: "Speech analysis, syllable stress markers, phonetic breakdowns, and practice drills.", te: "మాటల విశ్లేషణ, అక్షర ఒత్తిడి గుర్తులు, ధ్వని విభజనలు మరియు అభ్యాస సాధనలు.", hi: "स्पीच विश्लेषण, शब्दांश तनाव मार्कर, ध्वन्यात्मक विश्लेषण और अभ्यास ड्रिल।", ta: "பேச்சு பகுப்பாய்வு, எழுத்தழுத்த குறிகள், ஒலி பகுப்பாய்வுகள் மற்றும் பயிற்சி பயிற்சிகள்.", kn: "ಭಾಷಣ ವಿಶ್ಲೇಷಣೆ, ಉಚ್ಚಾರಾಂಶ ಒತ್ತಡ ಗುರುತುಗಳು, ಧ್ವನಿ ವಿಭಜನೆಗಳು ಮತ್ತು ಅಭ್ಯಾಸ ಡ್ರಿಲ್‌ಗಳು.", bn: "কথন বিশ্লেষণ, শব্দাংশ চাপ চিহ্নিতকারী, ধ্বনিগত বিশ্লেষণ ও অনুশীলন ড্রিল।", mr: "भाषण विश्लेषण, अक्षर ताण चिन्हे, ध्वनी विभाजन व सराव ड्रिल." },
  "dashboard.pillar_pronunciation_footer": { en: "Speech Coach", te: "మాటల కోచ్", hi: "स्पीच कोच", ta: "பேச்சு பயிற்சியாளர்", kn: "ಭಾಷಣ ತರಬೇತುದಾರ", bn: "স্পিচ কোচ", mr: "भाषण प्रशिक्षक" },
  "dashboard.badge_rapid": { en: "RAPID", te: "వేగవంతమైన", hi: "रैपिड", ta: "விரைவு", kn: "ವೇಗದ", bn: "দ্রুত", mr: "जलद" },
  "dashboard.pillar_stress_desc": { en: "Fast-paced speaking challenges with countdown timers to build spontaneous conversational agility.", te: "ఆకస్మిక సంభాషణ చురుకుదనాన్ని పెంపొందించడానికి కౌంట్‌డౌన్ టైమర్‌లతో వేగవంతమైన మాట్లాడే సవాళ్లు.", hi: "स्वतःस्फूर्त संवादात्मक चपलता बनाने के लिए काउंटडाउन टाइमर के साथ तेज़ गति से बोलने की चुनौतियाँ।", ta: "தன்னிச்சையான உரையாடல் விரைவை உருவாக்க எண்ணிறக்க டைமர்களுடன் வேகமான பேச்சு சவால்கள்.", kn: "ಸ್ವಯಂಪ್ರೇರಿತ ಸಂಭಾಷಣಾ ಚುರುಕುತನ ನಿರ್ಮಿಸಲು ಕೌಂಟ್‌ಡೌನ್ ಟೈಮರ್‌ಗಳೊಂದಿಗೆ ವೇಗದ ಮಾತುಗಾರಿಕೆ ಸವಾಲುಗಳು.", bn: "স্বতঃস্ফূর্ত কথোপকথন তত্পরতা তৈরি করতে কাউন্টডাউন টাইমারসহ দ্রুতগতির কথন চ্যালেঞ্জ।", mr: "उत्स्फूर्त संभाषण चपळता निर्माण करण्यासाठी काउंटडाउन टाइमरसह जलद बोलण्याची आव्हाने." },
  "dashboard.pillar_stress_footer": { en: "Timed Agility Simulator", te: "సమయ చురుకుదనం సిమ్యులేటర్", hi: "समयबद्ध चपलता सिम्युलेटर", ta: "நேரக் கட்டுப்பாட்டு விரைவு உருவகப்படுத்தி", kn: "ಸಮಯಬದ್ಧ ಚುರುಕುತನ ಸಿಮ್ಯುಲೇಟರ್", bn: "সময়সীমার তত্পরতা সিমুলেটর", mr: "वेळमर्यादित चपळता सिम्युलेटर" },
  "dashboard.badge_ai_diagnosis": { en: "AI DIAGNOSIS", te: "AI నిర్ధారణ", hi: "AI निदान", ta: "AI நோயறிதல்", kn: "AI ರೋಗನಿರ್ಣಯ", bn: "AI নির্ণয়", mr: "AI निदान" },
  "dashboard.pillar_doctor_desc": { en: "Analyze sentences for CEFR nuance, grammatical correctness, syntax improvements, and natural phrasing.", te: "CEFR సూక్ష్మభేదం, వ్యాకరణ సరైనతనం, వాక్య నిర్మాణ మెరుగుదలలు మరియు సహజ వ్యక్తీకరణ కోసం వాక్యాలను విశ్లేషించండి.", hi: "CEFR बारीकी, व्याकरणिक शुद्धता, वाक्य-रचना सुधार और स्वाभाविक वाक्यांश के लिए वाक्यों का विश्लेषण करें।", ta: "CEFR நுணுக்கம், இலக்கண சரிநிலை, தொடரியல் மேம்பாடுகள் மற்றும் இயல்பான சொற்றொடருக்கு வாக்கியங்களை பகுப்பாய்வு செய்யுங்கள்.", kn: "CEFR ಸೂಕ್ಷ್ಮತೆ, ವ್ಯಾಕರಣ ಸರಿತನ, ವಾಕ್ಯ ರಚನಾ ಸುಧಾರಣೆಗಳು ಮತ್ತು ಸಹಜ ವಾಕ್ಯರಚನೆಗಾಗಿ ವಾಕ್ಯಗಳನ್ನು ವಿಶ್ಲೇಷಿಸಿ.", bn: "CEFR সূক্ষ্মতা, ব্যাকরণগত সঠিকতা, বাক্যগঠন উন্নতি ও স্বাভাবিক বাক্যাংশের জন্য বাক্য বিশ্লেষণ করুন।", mr: "CEFR सूक्ष्मता, व्याकरण अचूकता, वाक्यरचना सुधारणा व नैसर्गिक वाक्यरचनेसाठी वाक्यांचे विश्लेषण करा." },
  "dashboard.pillar_doctor_footer": { en: "Instant Grammar Diagnosis", te: "తక్షణ వ్యాకరణ నిర్ధారణ", hi: "तत्काल व्याकरण निदान", ta: "உடனடி இலக்கண நோயறிதல்", kn: "ತಕ್ಷಣದ ವ್ಯಾಕರಣ ರೋಗನಿರ್ಣಯ", bn: "তাৎক্ষণিক ব্যাকরণ নির্ণয়", mr: "त्वरित व्याकरण निदान" },
