  "dashboard.explore_all_quizzes": { en: "Explore All Quizzes", te: "అన్ని క్విజ్‌లను అన్వేషించండి", hi: "सभी क्विज़ का अन्वेषण करें", ta: "அனைத்து வினாடி வினாக்களையும் ஆராயுங்கள்", kn: "ಎಲ್ಲಾ ಕ್ವಿಜ್‌ಗಳನ್ನು ಅನ್ವೇಷಿಸಿ", bn: "সব কুইজ অন্বেষণ করুন", mr: "सर्व प्रश्नमंजुषा शोधा" },
  "dashboard.quiz_challenge_badge": { en: "Quiz Challenge", te: "క్విజ్ సవాలు", hi: "क्विज़ चुनौती", ta: "வினாடி வினா சவால்", kn: "ಕ್ವಿಜ್ ಸವಾಲು", bn: "কুইজ চ্যালেঞ্জ", mr: "प्रश्नमंजुषा आव्हान" },
