  "dashboard.diagnostic_quiz_title": { en: "English Grammar Core Diagnostic", te: "ఆంగ్ల వ్యాకరణ ప్రధాన నిర్ధారణ", hi: "अंग्रेज़ी व्याकरण मुख्य निदान", ta: "ஆங்கில இலக்கண மைய நோயறிதல்", kn: "ಇಂಗ್ಲಿಷ್ ವ್ಯಾಕರಣ ಪ್ರಮುಖ ರೋಗನಿರ್ಣಯ", bn: "ইংরেজি ব্যাকরণ মূল নির্ণয়", mr: "इंग्रजी व्याकरण मुख्य निदान" },
  "dashboard.diagnostic_quiz_desc": { en: "Assess your mastery of tenses, subject-verb agreement, and error identification.", te: "కాలాలు, కర్త-క్రియ అన్వయం మరియు తప్పు గుర్తింపుపై మీ నైపుణ్యాన్ని అంచనా వేయండి.", hi: "काल, कर्ता-क्रिया सहमति, और त्रुटि पहचान में अपनी महारत का आकलन करें।", ta: "காலங்கள், எழுவாய்-வினை உடன்பாடு மற்றும் தவறு அடையாளத்தில் உங்கள் தேர்ச்சியை மதிப்பிடுங்கள்.", kn: "ಕಾಲಗಳು, ಕರ್ತೃ-ಕ್ರಿಯಾಪದ ಒಪ್ಪಂದ ಮತ್ತು ದೋಷ ಗುರುತಿಸುವಿಕೆಯಲ್ಲಿ ನಿಮ್ಮ ಪಾಂಡಿತ್ಯವನ್ನು ಮೌಲ್ಯಮಾಪನ ಮಾಡಿ.", bn: "কাল, কর্তা-ক্রিয়া সামঞ্জস্য ও ত্রুটি শনাক্তকরণে আপনার দক্ষতা মূল্যায়ন করুন।", mr: "काळ, कर्ता-क्रियापद सुसंगती व चूक ओळख यातील तुमचे प्रावीण्य तपासा." },
  "dashboard.start_practice_quiz": { en: "Start Practice Quiz (+50 XP)", te: "అభ్యాస క్విజ్‌ను ప్రారంభించండి (+50 XP)", hi: "अभ्यास क्विज़ शुरू करें (+50 XP)", ta: "பயிற்சி வினாடி வினாவைத் தொடங்கு (+50 XP)", kn: "ಅಭ್ಯಾಸ ಕ್ವಿಜ್ ಪ್ರಾರಂಭಿಸಿ (+50 XP)", bn: "অনুশীলন কুইজ শুরু করুন (+50 XP)", mr: "सराव प्रश्नमंजुषा सुरू करा (+50 XP)" },
  "dashboard.ai_doctor_badge": { en: "AI Doctor", te: "AI డాక్టర్", hi: "AI डॉक्टर", ta: "AI மருத்துவர்", kn: "AI ವೈದ್ಯ", bn: "AI ডাক্তার", mr: "AI डॉक्टर" },
  "dashboard.instant_analysis": { en: "Instant Analysis", te: "తక్షణ విశ్లేషణ", hi: "तत्काल विश्लेषण", ta: "உடனடி பகுப்பாய்வு", kn: "ತಕ್ಷಣದ ವಿಶ್ಲೇಷಣೆ", bn: "তাৎক্ষণিক বিশ্লেষণ", mr: "त्वरित विश्लेषण" },
  "dashboard.grammar_doctor_desc": { en: "Paste any complex English sentence to analyze parts of speech, tenses, and natural improvements.", te: "పద భాగాలు, కాలాలు మరియు సహజ మెరుగుదలలను విశ్లేషించడానికి ఏదైనా సంక్లిష్ట ఆంగ్ల వాక్యాన్ని పేస్ట్ చేయండి.", hi: "शब्द-भेद, काल, और स्वाभाविक सुधारों का विश्लेषण करने के लिए कोई भी जटिल अंग्रेज़ी वाक्य पेस्ट करें।", ta: "சொல் வகைகள், காலங்கள் மற்றும் இயல்பான மேம்பாடுகளை பகுப்பாய்வு செய்ய சிக்கலான ஆங்கில வாக்கியத்தை ஒட்டவும்.", kn: "ಪದ ಭಾಗಗಳು, ಕಾಲಗಳು ಮತ್ತು ಸಹಜ ಸುಧಾರಣೆಗಳನ್ನು ವಿಶ್ಲೇಷಿಸಲು ಯಾವುದೇ ಸಂಕೀರ್ಣ ಇಂಗ್ಲಿಷ್ ವಾಕ್ಯವನ್ನು ಅಂಟಿಸಿ.", bn: "বাক্যাংশ, কাল ও স্বাভাবিক উন্নতি বিশ্লেষণ করতে যেকোনো জটিল ইংরেজি বাক্য পেস্ট করুন।", mr: "शब्दभेद, काळ व नैसर्गिक सुधारणा विश्लेषित करण्यासाठी कोणतेही क्लिष्ट इंग्रजी वाक्य पेस्ट करा." },
  "dashboard.analyze_any_sentence": { en: "Analyze Any Sentence", te: "ఏదైనా వాక్యాన్ని విశ్లేషించండి", hi: "किसी भी वाक्य का विश्लेषण करें", ta: "எந்த வாக்கியத்தையும் பகுப்பாய்வு செய்யுங்கள்", kn: "ಯಾವುದೇ ವಾಕ್ಯವನ್ನು ವಿಶ್ಲೇಷಿಸಿ", bn: "যেকোনো বাক্য বিশ্লেষণ করুন", mr: "कोणतेही वाक्य विश्लेषण करा" },
