  "c2.benchmark_cta_desc": { en: "Verify your oral fluency, grammar accuracy, and vocabulary depth to unlock the next milestone towards C2.", te: "C2 వైపు తదుపరి మైలురాయిని అన్‌లాక్ చేయడానికి మీ మౌఖిక ధారాళత, వ్యాకరణ ఖచ్చితత్వం మరియు పదజాల లోతును ధృవీకరించండి.", hi: "C2 की ओर अगला माइलस्टोन अनलॉक करने के लिए अपनी मौखिक प्रवाह, व्याकरण सटीकता और शब्दावली गहराई सत्यापित करें।", ta: "C2 நோக்கிய அடுத்த மைல்கல்லைத் திறக்க உங்கள் வாய்மொழி சரளம், இலக்கண துல்லியம் மற்றும் சொல் ஆழத்தை சரிபார்க்கவும்.", kn: "C2 ಕಡೆಗೆ ಮುಂದಿನ ಮೈಲಿಗಲ್ಲನ್ನು ಅನ್‌ಲಾಕ್ ಮಾಡಲು ನಿಮ್ಮ ಮೌಖಿಕ ನಿರರ್ಗಳತೆ, ವ್ಯಾಕರಣ ನಿಖರತೆ ಮತ್ತು ಶಬ್ದಕೋಶ ಆಳವನ್ನು ಪರಿಶೀಲಿಸಿ.", bn: "C2-এর দিকে পরবর্তী মাইলফলক আনলক করতে আপনার মৌখিক সাবলীলতা, ব্যাকরণ নির্ভুলতা ও শব্দভাণ্ডার গভীরতা যাচাই করুন।", mr: "C2 कडे पुढील टप्पा अनलॉक करण्यासाठी तुमची तोंडी अस्खलितता, व्याकरण अचूकता व शब्दसंग्रह खोली तपासा." },
  "c2.start_benchmark_prefix": { en: "Start", te: "ప్రారంభించండి", hi: "शुरू करें", ta: "தொடங்கு", kn: "ಪ್ರಾರಂಭಿಸಿ", bn: "শুরু করুন", mr: "सुरू करा" },
  "c2.start_benchmark_suffix": { en: "Benchmark Test", te: "బెంచ్‌మార్క్ పరీక్ష", hi: "बेंचमार्क परीक्षा", ta: "அளவுகோள் தேர்வு", kn: "ಬೆಂಚ್‌ಮಾರ್ಕ್ ಪರೀಕ್ಷೆ", bn: "বেঞ্চমার্ক পরীক্ষা", mr: "बेंचमार्क परीक्षा" },
  "c2.ai_dynamic_generator": { en: "AI Dynamic Module Generator", te: "AI డైనమిక్ మాడ్యూల్ జనరేటర్", hi: "AI गतिशील मॉड्यूल जनरेटर", ta: "AI மாறும் தொகுதி உருவாக்கி", kn: "AI ಡೈನಾಮಿಕ್ ಮಾಡ್ಯೂಲ್ ಜನರೇಟರ್", bn: "AI ডাইনামিক মডিউল জেনারেটর", mr: "AI डायनॅमिक मॉड्यूल जनरेटर" },
  "c2.ai_generator_desc": { en: "Have Gemini craft a personalized, high-intensity C2 drill tailored directly to your recent speaking weaknesses.", te: "మీ ఇటీవలి మాట్లాడే బలహీనతలకు అనుగుణంగా Gemini వ్యక్తిగతీకరించిన, అధిక-తీవ్రత C2 సాధనను రూపొందించనివ్వండి.", hi: "Gemini से अपनी हाल की बोलने की कमज़ोरियों के अनुरूप व्यक्तिगत, उच्च-तीव्रता वाला C2 अभ्यास तैयार करवाएं।", ta: "உங்கள் சமீபத்திய பேச்சு பலவீனங்களுக்கு நேரடியாக ஏற்ப Gemini தனிப்பயன், அதிக-தீவிர C2 பயிற்சியை உருவாக்கட்டும்.", kn: "ನಿಮ್ಮ ಇತ್ತೀಚಿನ ಮಾತುಗಾರಿಕೆ ದೌರ್ಬಲ್ಯಗಳಿಗೆ ನೇರವಾಗಿ ಹೊಂದಿಸಲಾದ ವೈಯಕ್ತಿಕ, ಹೆಚ್ಚಿನ-ತೀವ್ರತೆಯ C2 ಡ್ರಿಲ್ ಅನ್ನು Gemini ರಚಿಸಲಿ.", bn: "আপনার সাম্প্রতিক কথনের দুর্বলতার সাথে খাপ খাওয়ানো ব্যক্তিগতকৃত, উচ্চ-তীব্রতার C2 ড্রিল তৈরি করতে Gemini-কে দিন।", mr: "तुमच्या अलीकडील बोलण्याच्या कमकुवतपणाला थेट अनुरूप वैयक्तिकृत, उच्च-तीव्रता C2 सराव Gemini कडून तयार करून घ्या." },
  "c2.synthesizing_blueprint": { en: "Synthesizing C2 Blueprint...", te: "C2 బ్లూప్రింట్‌ను సంశ్లేషణ చేస్తోంది...", hi: "C2 ब्लूप्रिंट संश्लेषित किया जा रहा है...", ta: "C2 வரைபடம் தொகுக்கப்படுகிறது...", kn: "C2 ಬ್ಲೂಪ್ರಿಂಟ್ ಸಂಶ್ಲೇಷಿಸಲಾಗುತ್ತಿದೆ...", bn: "C2 ব্লুপ্রিন্ট সংশ্লেষণ করা হচ্ছে...", mr: "C2 ब्लूप्रिंट तयार होत आहे..." },
  "c2.generate_custom_drill": { en: "Generate Custom AI Drill", te: "అనుకూల AI సాధనను రూపొందించండి", hi: "कस्टम AI अभ्यास बनाएं", ta: "தனிப்பயன் AI பயிற்சியை உருவாக்கு", kn: "ಕಸ್ಟಮ್ AI ಡ್ರಿಲ್ ರಚಿಸಿ", bn: "কাস্টম AI ড্রিল তৈরি করুন", mr: "सानुकूल AI सराव तयार करा" },
  "c2.custom_drill_ready": { en: "Custom Dynamic C2 Drill Ready:", te: "అనుకూల డైనమిక్ C2 సాధన సిద్ధంగా ఉంది:", hi: "कस्टम गतिशील C2 अभ्यास तैयार:", ta: "தனிப்பயன் மாறும் C2 பயிற்சி தயார்:", kn: "ಕಸ್ಟಮ್ ಡೈನಾಮಿಕ್ C2 ಡ್ರಿಲ್ ಸಿದ್ಧವಿದೆ:", bn: "কাস্টম ডাইনামিক C2 ড্রিল প্রস্তুত:", mr: "सानुकूल डायनॅमिक C2 सराव तयार:" },

