  "assessment.engine_badge": { en: "GLOBAL AI ASSESSMENT & INTEGRITY PIPELINE", te: "గ్లోబల్ AI అసెస్‌మెంట్ & సమగ్రత పైప్‌లైన్", hi: "ग्लोबल AI मूल्यांकन और सत्यनिष्ठा पाइपलाइन", ta: "உலகளாவிய AI மதிப்பீடு & நேர்மைப் பாதை", kn: "ಜಾಗತಿಕ AI ಮೌಲ್ಯಮಾಪನ ಮತ್ತು ಸಮಗ್ರತೆ ಪೈಪ್‌ಲೈನ್", bn: "গ্লোবাল AI মূল্যায়ন ও সততা পাইপলাইন", mr: "ग्लोबल AI मूल्यांकन आणि सचोटी पाइपलाइन" },
  "assessment.title": { en: "Unified Assessment Engine", te: "ఏకీకృత అసెస్‌మెంట్ ఇంజిన్", hi: "एकीकृत मूल्यांकन इंजन", ta: "ஒருங்கிணைந்த மதிப்பீட்டு இயந்திரம்", kn: "ಏಕೀಕೃತ ಮೌಲ್ಯಮಾಪನ ಎಂಜಿನ್", bn: "একীভূত মূল্যায়ন ইঞ্জিন", mr: "एकत्रित मूल्यांकन इंजिन" },
  "assessment.subtitle_part1": { en: "All Speaking, Writing, and Grammar AI evaluations are routed through the mandatory Plagiarism & Integrity Gate. Every evaluation output strictly adheres to the standardized", te: "మాట్లాడటం, రాయడం మరియు వ్యాకరణం సంబంధిత అన్ని AI మూల్యాంకనాలు తప్పనిసరి దొంగతనం & సమగ్రత గేట్ ద్వారా పంపబడతాయి. ప్రతి మూల్యాంకన ఫలితం ప్రామాణిక", hi: "सभी बोलने, लेखन और व्याकरण संबंधी AI मूल्यांकन अनिवार्य साहित्यिक चोरी और सत्यनिष्ठा गेट से होकर गुजरते हैं। हर मूल्यांकन परिणाम मानकीकृत", ta: "பேச்சு, எழுத்து மற்றும் இலக்கணம் தொடர்பான அனைத்து AI மதிப்பீடுகளும் கட்டாய கருத்துத் திருட்டு & நேர்மை நுழைவாயில் வழியாக அனுப்பப்படுகின்றன. ஒவ்வொரு மதிப்பீட்டு வெளியீடும் தரப்படுத்தப்பட்ட", kn: "ಎಲ್ಲಾ ಮಾತನಾಡುವಿಕೆ, ಬರವಣಿಗೆ ಮತ್ತು ವ್ಯಾಕರಣ AI ಮೌಲ್ಯಮಾಪನಗಳು ಕಡ್ಡಾಯ ಕೃತಿಚೌರ್ಯ ಮತ್ತು ಸಮಗ್ರತೆ ಗೇಟ್ ಮೂಲಕ ಹಾದುಹೋಗುತ್ತವೆ. ಪ್ರತಿ ಮೌಲ್ಯಮಾಪನ ಫಲಿತಾಂಶವು ಪ್ರಮಾಣಿತ", bn: "সমস্ত কথন, লেখা এবং ব্যাকরণ সংক্রান্ত AI মূল্যায়ন বাধ্যতামূলক চুরি ও সততা গেট দিয়ে পরিচালিত হয়। প্রতিটি মূল্যায়ন ফলাফল প্রমিত", mr: "सर्व बोलणे, लेखन आणि व्याकरण संबंधित AI मूल्यांकने अनिवार्य साहित्यिक चोरी व सचोटी गेटमधून पाठवली जातात. प्रत्येक मूल्यांकन निकाल प्रमाणित" },
  "assessment.subtitle_and": { en: "and", te: "మరియు", hi: "और", ta: "மற்றும்", kn: "ಮತ್ತು", bn: "এবং", mr: "आणि" },
  "assessment.subtitle_schema": { en: "schema.", te: "స్కీమాకు కట్టుబడి ఉంటుంది.", hi: "स्कीमा का पालन करता है।", ta: "திட்டவடிவத்தைப் பின்பற்றுகிறது.", kn: "ಸ್ಕೀಮಾವನ್ನು ಅನುಸರಿಸುತ್ತದೆ.", bn: "স্কিমা অনুসরণ করে।", mr: "स्कीमाचे पालन करते." },
