  "assessment.mode_writing": { en: "Writing Assessment", te: "రచనా మూల్యాంకనం", hi: "लेखन मूल्यांकन", ta: "எழுத்து மதிப்பீடு", kn: "ಬರವಣಿಗೆ ಮೌಲ್ಯಮಾಪನ", bn: "লেখা মূল্যায়ন", mr: "लेखन मूल्यांकन" },
