  "assessment.mode_studio": { en: "Integrity Studio", te: "సమగ్రత స్టూడియో", hi: "सत्यनिष्ठा स्टूडियो", ta: "நேர்மை ஸ்டூடியோ", kn: "ಸಮಗ್ರತೆ ಸ್ಟುಡಿಯೋ", bn: "সততা স্টুডিও", mr: "सचोटी स्टुडिओ" },
  "assessment.speaking_banner_title": { en: "Oral Proficiency CEFR Assessor • Protected by Integrity Gate", te: "మౌఖిక ప్రావీణ్య CEFR మూల్యాంకకుడు • సమగ్రత గేట్ ద్వారా రక్షించబడింది", hi: "मौखिक दक्षता CEFR मूल्यांकनकर्ता • सत्यनिष्ठा गेट द्वारा सुरक्षित", ta: "வாய்மொழி திறன் CEFR மதிப்பீட்டாளர் • நேர்மை நுழைவாயிலால் பாதுகாக்கப்பட்டது", kn: "ಮೌಖಿಕ ಪ್ರಾವೀಣ್ಯ CEFR ಮೌಲ್ಯಮಾಪಕ • ಸಮಗ್ರತೆ ಗೇಟ್‌ನಿಂದ ಸಂರಕ್ಷಿತ", bn: "মৌখিক দক্ষতা CEFR মূল্যায়নকারী • সততা গেট দ্বারা সুরক্ষিত", mr: "तोंडी प्रावीण्य CEFR मूल्यांकनकर्ता • सचोटी गेटद्वारे संरक्षित" },
  "assessment.speaking_banner_desc": { en: "Transcripts are continuously cross-examined for read-aloud flags, canned response templates, and AI generation markers.", te: "ట్రాన్స్క్రిప్ట్‌లు చదివి వినిపించే ఫ్లాగ్‌లు, రెడీమేడ్ సమాధాన మూసలు మరియు AI జనరేషన్ గుర్తుల కోసం నిరంతరం క్రాస్-పరీక్షించబడతాయి.", hi: "प्रतिलिपियों की लगातार पढ़-कर-सुनाई गई प्रतिक्रियाओं, तैयार उत्तर टेम्पलेट्स और AI-जनित संकेतकों के लिए जांच की जाती है।", ta: "பிரதிகள் தொடர்ந்து உரக்கப் படித்தல் கொடிகள், தயார் பதில் வார்ப்புருக்கள் மற்றும் AI உருவாக்க அடையாளங்களுக்காக குறுக்கு சோதிக்கப்படுகின்றன.", kn: "ಪ್ರತಿಲಿಪಿಗಳನ್ನು ಗಟ್ಟಿಯಾಗಿ-ಓದುವ ಫ್ಲ್ಯಾಗ್‌ಗಳು, ಸಿದ್ಧ ಉತ್ತರ ಟೆಂಪ್ಲೇಟ್‌ಗಳು ಮತ್ತು AI ರಚನೆ ಗುರುತುಗಳಿಗಾಗಿ ನಿರಂತರವಾಗಿ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ.", bn: "প্রতিলিপিগুলো ক্রমাগত জোরে-পড়া ফ্ল্যাগ, প্রস্তুত উত্তর টেমপ্লেট এবং AI-উৎপন্ন চিহ্নের জন্য পরীক্ষা করা হয়।", mr: "प्रतिलिपींची सतत मोठ्याने-वाचलेली उत्तरे, तयार उत्तर साचे आणि AI-निर्मित खुणांसाठी तपासणी केली जाते." },
  "assessment.standard_json_enabled": { en: "Standard JSON Enabled", te: "ప్రామాణిక JSON ప్రారంభించబడింది", hi: "मानक JSON सक्षम", ta: "நிலையான JSON இயக்கப்பட்டது", kn: "ಪ್ರಮಾಣಿತ JSON ಸಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ", bn: "স্ট্যান্ডার্ড JSON সক্রিয়", mr: "मानक JSON सक्षम" },
  "assessment.writing_title": { en: "Writing Performance & Originality Evaluator", te: "రచనా పనితీరు & వాస్తవికత మూల్యాంకనం", hi: "लेखन प्रदर्शन और मौलिकता मूल्यांकनकर्ता", ta: "எழுத்து செயல்திறன் & மௌலிகத் தன்மை மதிப்பீட்டாளர்", kn: "ಬರವಣಿಗೆ ಕಾರ್ಯಕ್ಷಮತೆ ಮತ್ತು ಮೌಲಿಕತೆ ಮೌಲ್ಯಮಾಪಕ", bn: "লেখার পারফরম্যান্স ও মৌলিকত্ব মূল্যায়নকারী", mr: "लेखन कामगिरी व मौलिकता मूल्यांकनकर्ता" },
  "assessment.writing_desc": { en: "Evaluates task achievement, syntactic range, cohesion, and verifies authenticity.", te: "టాస్క్ సాధన, వాక్య నిర్మాణ వైవిధ్యం, పొందిక మరియు వాస్తవికతను ధృవీకరిస్తుంది.", hi: "कार्य पूर्णता, वाक्य-रचना विविधता, सुसंगति का मूल्यांकन करता है और प्रामाणिकता सत्यापित करता है।", ta: "பணி நிறைவேற்றம், தொடரியல் வீச்சு, ஒருங்கிணைப்பு ஆகியவற்றை மதிப்பிட்டு நம்பகத்தன்மையை சரிபார்க்கிறது.", kn: "ಕಾರ್ಯ ಸಾಧನೆ, ವಾಕ್ಯ ರಚನಾ ವ್ಯಾಪ್ತಿ, ಒಗ್ಗಟ್ಟನ್ನು ಮೌಲ್ಯಮಾಪನ ಮಾಡಿ ಸತ್ಯಾಸತ್ಯತೆಯನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ.", bn: "কাজের সম্পাদন, বাক্যগঠন বৈচিত্র্য, সংহতি মূল্যায়ন করে এবং সত্যতা যাচাই করে।", mr: "कार्य साध्यता, वाक्यरचना विविधता, सुसंगती यांचे मूल्यांकन करते व सत्यता पडताळते." },
