  // Plagiarism Integrity Studio
  "plagiarism.engine_badge": { en: "Automated Plagiarism & Academic Integrity Engine", te: "ఆటోమేటెడ్ దొంగతనం & విద్యా సమగ్రత ఇంజిన్", hi: "स्वचालित साहित्यिक चोरी और शैक्षणिक सत्यनिष्ठा इंजन", ta: "தானியங்கு கருத்துத் திருட்டு & கல்வி நேர்மை இயந்திரம்", kn: "ಸ್ವಯಂಚಾಲಿತ ಕೃತಿಚೌರ್ಯ ಮತ್ತು ಶೈಕ್ಷಣಿಕ ಸಮಗ್ರತೆ ಎಂಜಿನ್", bn: "স্বয়ংক্রিয় চুরি ও শিক্ষাগত সততা ইঞ্জিন", mr: "स्वयंचलित साहित्यिक चोरी व शैक्षणिक सचोटी इंजिन" },
  "plagiarism.title": { en: "Assessment Evaluation & Integrity Analysis", te: "అసెస్‌మెంట్ మూల్యాంకనం & సమగ్రత విశ్లేషణ", hi: "मूल्यांकन आकलन और सत्यनिष्ठा विश्लेषण", ta: "மதிப்பீட்டு மதிப்பீடு & நேர்மை பகுப்பாய்வு", kn: "ಮೌಲ್ಯಮಾಪನ ಮತ್ತು ಸಮಗ್ರತೆ ವಿಶ್ಲೇಷಣೆ", bn: "মূল্যায়ন যাচাই ও সততা বিশ্লেষণ", mr: "मूल्यांकन तपासणी व सचोटी विश्लेषण" },
  "plagiarism.subtitle": { en: "Every assessment output returns a structured JSON payload coupling educational performance evaluation with multi-metric plagiarism detection, synthetic AI probability auditing, and flagged passage telemetry.", te: "ప్రతి అసెస్‌మెంట్ ఫలితం విద్యా పనితీరు మూల్యాంకనాన్ని బహుళ-కొలత దొంగతనం గుర్తింపు, కృత్రిమ AI సంభావ్యత తనిఖీ మరియు గుర్తించబడిన భాగాల టెలిమెట్రీతో కలిపి నిర్మాణాత్మక JSON పేలోడ్‌గా అందిస్తుంది.", hi: "प्रत्येक मूल्यांकन परिणाम शैक्षणिक प्रदर्शन आकलन को बहु-मापदंड साहित्यिक चोरी पहचान, कृत्रिम AI संभावना ऑडिटिंग, और चिह्नित अंश टेलीमेट्री के साथ जोड़ते हुए एक संरचित JSON पेलोड लौटाता है।", ta: "ஒவ்வொரு மதிப்பீட்டு வெளியீடும் கல்வி செயல்திறன் மதிப்பீட்டை பல-அளவீட்டு கருத்துத் திருட்டு கண்டறிதல், செயற்கை AI நிகழ்தகவு தணிக்கை மற்றும் குறியிடப்பட்ட பத்தி தரவுடன் இணைத்து ஒரு கட்டமைக்கப்பட்ட JSON சுமையை வழங்குகிறது.", kn: "ಪ್ರತಿ ಮೌಲ್ಯಮಾಪನ ಫಲಿತಾಂಶವು ಶೈಕ್ಷಣಿಕ ಕಾರ್ಯಕ್ಷಮತೆ ಮೌಲ್ಯಮಾಪನವನ್ನು ಬಹು-ಮಾಪನ ಕೃತಿಚೌರ್ಯ ಪತ್ತೆ, ಕೃತಕ AI ಸಂಭವನೀಯತೆ ಲೆಕ್ಕಪರಿಶೋಧನೆ ಮತ್ತು ಫ್ಲ್ಯಾಗ್ ಮಾಡಿದ ಭಾಗ ಟೆಲಿಮೆಟ್ರಿಯೊಂದಿಗೆ ಜೋಡಿಸಿ ರಚನಾತ್ಮಕ JSON ಪೇಲೋಡ್ ಅನ್ನು ಹಿಂತಿರುಗಿಸುತ್ತದೆ.", bn: "প্রতিটি মূল্যায়ন ফলাফল শিক্ষাগত কর্মক্ষমতা মূল্যায়নকে বহু-মাত্রিক চুরি শনাক্তকরণ, কৃত্রিম AI সম্ভাবনা অডিটিং এবং চিহ্নিত অংশ টেলিমেট্রির সাথে যুক্ত করে একটি কাঠামোবদ্ধ JSON পেলোড ফেরত দেয়।", mr: "प्रत्येक मूल्यांकन निकाल शैक्षणिक कामगिरी मूल्यांकनाला बहु-मापदंड साहित्यिक चोरी शोध, कृत्रिम AI संभाव्यता तपासणी व चिन्हांकित उतारा टेलिमेट्रीसह जोडून रचनात्मक JSON पेलोड परत करतो." },
