  "plagiarism.flagged_telemetry_label": { en: "Flagged Passages & Telemetry", te: "గుర్తించబడిన భాగాలు & టెలిమెట్రీ", hi: "चिह्नित अंश और टेलीमेट्री", ta: "குறியிடப்பட்ட பத்திகள் & தரவு", kn: "ಫ್ಲ್ಯಾಗ್ ಮಾಡಿದ ಭಾಗಗಳು ಮತ್ತು ಟೆಲಿಮೆಟ್ರಿ", bn: "চিহ্নিত অংশ ও টেলিমেট্রি", mr: "चिन्हांकित उतारे व टेलिमेट्री" },
  "plagiarism.no_anomalous_passages": { en: "No anomalous passages flagged", te: "ఏ అసాధారణ భాగాలు గుర్తించబడలేదు", hi: "कोई असामान्य अंश चिह्नित नहीं", ta: "எந்த முரண்பாடான பத்தியும் குறியிடப்படவில்லை", kn: "ಯಾವುದೇ ಅಸಹಜ ಭಾಗಗಳನ್ನು ಫ್ಲ್ಯಾಗ್ ಮಾಡಿಲ್ಲ", bn: "কোনো অস্বাভাবিক অংশ চিহ্নিত হয়নি", mr: "कोणतेही असामान्य उतारे चिन्हांकित नाहीत" },
  "plagiarism.inspect_flag": { en: "Inspect Flag & Improvement Tips", te: "ఫ్లాగ్ & మెరుగుదల చిట్కాలను పరిశీలించండి", hi: "फ़्लैग और सुधार सुझावों की जांच करें", ta: "கொடி & மேம்பாட்டுக் குறிப்புகளை ஆய்வு செய்", kn: "ಫ್ಲ್ಯಾಗ್ ಮತ್ತು ಸುಧಾರಣೆ ಸಲಹೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿ", bn: "ফ্ল্যাগ ও উন্নতির পরামর্শ পরীক্ষা করুন", mr: "फ्लॅग व सुधारणा टिप्स तपासा" },
  "plagiarism.click_drill_down": { en: "Click to drill down", te: "లోతుగా చూడటానికి క్లిక్ చేయండి", hi: "विवरण देखने के लिए क्लिक करें", ta: "விரிவாகக் காண கிளிக் செய்யவும்", kn: "ಆಳವಾಗಿ ನೋಡಲು ಕ್ಲಿಕ್ ಮಾಡಿ", bn: "বিস্তারিত দেখতে ক্লিক করুন", mr: "सविस्तर पाहण्यासाठी क्लिक करा" },
  "plagiarism.no_flags_desc": { en: "All submitted sentences demonstrate organic human structure, original phrasing, and valid contextual tone.", te: "సమర్పించిన అన్ని వాక్యాలు సహజ మానవ నిర్మాణం, అసలైన పదజాలం మరియు సముచిత సందర్భోచిత స్వరాన్ని ప్రదర్శిస్తాయి.", hi: "प्रस्तुत सभी वाक्य स्वाभाविक मानव संरचना, मौलिक वाक्यांश और उचित प्रासंगिक स्वर प्रदर्शित करते हैं।", ta: "சமர்ப்பிக்கப்பட்ட அனைத்து வாக்கியங்களும் இயற்கையான மனித அமைப்பு, மூல சொற்றொடர் மற்றும் சரியான சூழல் தொனியை காட்டுகின்றன.", kn: "ಸಲ್ಲಿಸಲಾದ ಎಲ್ಲಾ ವಾಕ್ಯಗಳು ಸಹಜ ಮಾನವ ರಚನೆ, ಮೂಲ ಪದಪ್ರಯೋಗ ಮತ್ತು ಸೂಕ್ತ ಸಂದರ್ಭೋಚಿತ ಧ್ವನಿಯನ್ನು ತೋರಿಸುತ್ತವೆ.", bn: "জমা দেওয়া সমস্ত বাক্য স্বাভাবিক মানব গঠন, মৌলিক বাক্যাংশ ও যথাযথ প্রাসঙ্গিক সুর প্রদর্শন করে।", mr: "सादर केलेली सर्व वाक्ये नैसर्गिक मानवी रचना, मूळ वाक्यरचना व योग्य संदर्भोचित सूर दर्शवतात." },
  "plagiarism.json_spec_title": { en: "Engine JSON Output Specification", te: "ఇంజిన్ JSON అవుట్‌పుట్ స్పెసిఫికేషన్", hi: "इंजन JSON आउटपुट विनिर्देश", ta: "இயந்திர JSON வெளியீட்டு விவரக்குறிப்பு", kn: "ಎಂಜಿನ್ JSON ಔಟ್‌ಪುಟ್ ವಿವರಣೆ", bn: "ইঞ্জিন JSON আউটপুট স্পেসিফিকেশন", mr: "इंजिन JSON आउटपुट तपशील" },
  "plagiarism.json_spec_desc": { en: "Strict JSON payload with `assessment` and `plagiarism_analysis` sections", te: "`assessment` మరియు `plagiarism_analysis` విభాగాలతో కఠినమైన JSON పేలోడ్", hi: "`assessment` और `plagiarism_analysis` अनुभागों के साथ सख्त JSON पेलोड", ta: "`assessment` மற்றும் `plagiarism_analysis` பிரிவுகளுடன் கடுமையான JSON சுமை", kn: "`assessment` ಮತ್ತು `plagiarism_analysis` ವಿಭಾಗಗಳೊಂದಿಗೆ ಕಟ್ಟುನಿಟ್ಟಾದ JSON ಪೇಲೋಡ್", bn: "`assessment` ও `plagiarism_analysis` অংশ সহ কঠোর JSON পেলোড", mr: "`assessment` व `plagiarism_analysis` विभागांसह काटेकोर JSON पेलोड" },
  "plagiarism.copied_bang": { en: "Copied!", te: "కాపీ చేయబడింది!", hi: "कॉपी हो गया!", ta: "நகலெடுக்கப்பட்டது!", kn: "ನಕಲಿಸಲಾಗಿದೆ!", bn: "কপি হয়েছে!", mr: "कॉपी झाले!" },
