  "plagiarism.download_report": { en: "Download Report", te: "నివేదికను డౌన్‌లోడ్ చేయండి", hi: "रिपोर्ट डाउनलोड करें", ta: "அறிக்கையைப் பதிவிறக்கு", kn: "ವರದಿಯನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ", bn: "রিপোর্ট ডাউনলোড করুন", mr: "अहवाल डाउनलोड करा" },
