  // Adaptive Module Configurator
  "adaptive.screen3_label": { en: "Screen 3: Adaptive CEFR Module Configurator", te: "స్క్రీన్ 3: అనుకూల CEFR మాడ్యూల్ కాన్ఫిగరేటర్", hi: "स्क्रीन 3: अनुकूली CEFR मॉड्यूल कॉन्फ़िगरेटर", ta: "திரை 3: தகவமைப்பு CEFR தொகுதி கட்டமைப்பாளர்", kn: "ಸ್ಕ್ರೀನ್ 3: ಅಡಾಪ್ಟಿವ್ CEFR ಮಾಡ್ಯೂಲ್ ಕಾನ್ಫಿಗರೇಟರ್", bn: "স্ক্রিন ৩: অভিযোজিত CEFR মডিউল কনফিগারেটর", mr: "स्क्रीन 3: अनुकूल CEFR मॉड्यूल कॉन्फिगरेटर" },
  "adaptive.personalized_curriculum_for": { en: "Personalized Spoken Curriculum for", te: "వ్యక్తిగతీకరించిన మాట్లాడే పాఠ్యాంశం", hi: "व्यक्तिगत मौखिक पाठ्यक्रम", ta: "தனிப்பயனாக்கப்பட்ட பேச்சுப் பாடத்திட்டம்", kn: "ವೈಯಕ್ತೀಕರಿಸಿದ ಮಾತುಗಾರಿಕೆ ಪಠ್ಯಕ್ರಮ", bn: "ব্যক্তিগতকৃত কথন পাঠ্যক্রম", mr: "वैयक्तिकृत बोलणे अभ्यासक्रम" },
  "adaptive.band_label": { en: "Band", te: "బ్యాండ్", hi: "बैंड", ta: "நிலை", kn: "ಬ್ಯಾಂಡ್", bn: "ব্যান্ড", mr: "बँड" },
  "adaptive.your_level": { en: "Your Level", te: "మీ స్థాయి", hi: "आपका स्तर", ta: "உங்கள் நிலை", kn: "ನಿಮ್ಮ ಹಂತ", bn: "আপনার স্তর", mr: "तुमचा स्तर" },
  "adaptive.banner_desc": { en: "Based on your oral proficiency assessment, lower levels have been automatically marked as tested out, and your curriculum starts right at your optimal communicative threshold.", te: "మీ మౌఖిక ప్రావీణ్య మూల్యాంకనం ఆధారంగా, తక్కువ స్థాయిలు ఆటోమేటిక్‌గా పరీక్షించి పూర్తయినట్లు గుర్తించబడ్డాయి మరియు మీ పాఠ్యాంశం మీ సరైన సంభాషణా స్థాయి వద్దే ప్రారంభమవుతుంది.", hi: "आपके मौखिक दक्षता मूल्यांकन के आधार पर, निचले स्तरों को स्वचालित रूप से परीक्षित माना गया है, और आपका पाठ्यक्रम सीधे आपके इष्टतम संचार स्तर से शुरू होता है।", ta: "உங்கள் வாய்மொழி திறன் மதிப்பீட்டின் அடிப்படையில், குறைந்த நிலைகள் தானாகவே தேர்வு செய்யப்பட்டதாக குறிக்கப்பட்டுள்ளன, மேலும் உங்கள் பாடத்திட்டம் உங்கள் உகந்த தொடர்பு நிலையிலேயே தொடங்குகிறது.", kn: "ನಿಮ್ಮ ಮೌಖಿಕ ಪ್ರಾವೀಣ್ಯ ಮೌಲ್ಯಮಾಪನದ ಆಧಾರದ ಮೇಲೆ, ಕೆಳಗಿನ ಹಂತಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಪರೀಕ್ಷಿತವೆಂದು ಗುರುತಿಸಲಾಗಿದೆ, ಮತ್ತು ನಿಮ್ಮ ಪಠ್ಯಕ್ರಮವು ನಿಮ್ಮ ಸೂಕ್ತ ಸಂವಹನ ಮಟ್ಟದಲ್ಲಿಯೇ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ.", bn: "আপনার মৌখিক দক্ষতা মূল্যায়নের ভিত্তিতে, নিম্ন স্তরগুলো স্বয়ংক্রিয়ভাবে পরীক্ষিত হিসেবে চিহ্নিত হয়েছে, এবং আপনার পাঠ্যক্রম সরাসরি আপনার সর্বোত্তম যোগাযোগ স্তর থেকে শুরু হয়।", mr: "तुमच्या तोंडी प्रावीण्य मूल्यांकनावर आधारित, खालचे स्तर आपोआप तपासलेले म्हणून चिन्हांकित केले गेले आहेत, आणि तुमचा अभ्यासक्रम थेट तुमच्या योग्य संवाद पातळीपासून सुरू होतो." },
  "adaptive.fluency_label": { en: "Fluency:", te: "ధారాళత:", hi: "प्रवाह:", ta: "சரளம்:", kn: "ನಿರರ್ಗಳತೆ:", bn: "সাবলীলতা:", mr: "अस्खलितता:" },
  "adaptive.grammar_label": { en: "Grammar:", te: "వ్యాకరణం:", hi: "व्याकरण:", ta: "இலக்கணம்:", kn: "ವ್ಯಾಕರಣ:", bn: "ব্যাকরণ:", mr: "व्याकरण:" },
