  // L2 Speaking Coach Studio (Roleplay Coach)
  "roleplay.hero_badge": { en: "INTERACTIVE SPEAKING COACH", te: "ఇంటరాక్టివ్ స్పీకింగ్ కోచ్", hi: "इंटरैक्टिव स्पीकिंग कोच", ta: "ஊடாடும் பேச்சு பயிற்சியாளர்", kn: "ಸಂವಾದಾತ್ಮಕ ಮಾತುಗಾರಿಕೆ ತರಬೇತುದಾರ", bn: "ইন্টারেক্টিভ স্পিকিং কোচ", mr: "संवादी बोलणे प्रशिक्षक" },
  "roleplay.natural_dialogue_practice": { en: "Natural Dialogue Practice", te: "సహజ సంభాషణ అభ్యాసం", hi: "स्वाभाविक संवाद अभ्यास", ta: "இயல்பான உரையாடல் பயிற்சி", kn: "ಸಹಜ ಸಂಭಾಷಣೆ ಅಭ್ಯಾಸ", bn: "স্বাভাবিক কথোপকথন অনুশীলন", mr: "नैसर्गिक संवाद सराव" },
  "roleplay.hero_title": { en: "Interactive Speaking Coach & Dynamic Scenarios", te: "ఇంటరాక్టివ్ స్పీకింగ్ కోచ్ & డైనమిక్ దృశ్యాలు", hi: "इंटरैक्टिव स्पीकिंग कोच और गतिशील परिदृश्य", ta: "ஊடாடும் பேச்சு பயிற்சியாளர் & மாறும் சூழ்நிலைகள்", kn: "ಸಂವಾದಾತ್ಮಕ ಮಾತುಗಾರಿಕೆ ತರಬೇತುದಾರ ಮತ್ತು ಡೈನಾಮಿಕ್ ಸನ್ನಿವೇಶಗಳು", bn: "ইন্টারেক্টিভ স্পিকিং কোচ ও ডাইনামিক দৃশ্যকল্প", mr: "संवादी बोलणे प्रशिक्षक व डायनॅमिक परिस्थिती" },
  "roleplay.hero_desc": { en: "Engage in realistic, multi-turn roleplay conversations to strengthen natural vocabulary recall, sentence framing, and conversational fluency. Get turn-by-turn feedback, supportive prompts if needed, and practice responding in your own words.", te: "సహజ పదజాల గుర్తుంపు, వాక్య నిర్మాణం మరియు సంభాషణా ధారాళతను బలోపేతం చేయడానికి వాస్తవిక, బహుళ-టర్న్ రోల్‌ప్లే సంభాషణల్లో పాల్గొనండి. టర్న్-బై-టర్న్ అభిప్రాయం, అవసరమైతే సహాయక సూచనలు మరియు మీ సొంత మాటల్లో సమాధానం ఇచ్చే అభ్యాసం పొందండి.", hi: "स्वाभाविक शब्दावली स्मरण, वाक्य निर्माण और संवादात्मक प्रवाह को मजबूत करने के लिए यथार्थवादी, बहु-चरण रोलप्ले संवादों में भाग लें। चरण-दर-चरण प्रतिक्रिया, आवश्यकता होने पर सहायक संकेत, और अपने शब्दों में उत्तर देने का अभ्यास प्राप्त करें।", ta: "இயல்பான சொல் நினைவகம், வாக்கிய அமைப்பு மற்றும் உரையாடல் சரளத்தை வலுப்படுத்த யதார்த்தமான, பல-முறை பாத்திரமேற்பு உரையாடல்களில் ஈடுபடுங்கள். ஒவ்வொரு முறையிலும் கருத்து, தேவைப்பட்டால் ஆதரவு தூண்டல்கள் மற்றும் உங்கள் சொந்த வார்த்தைகளில் பதிலளிக்கும் பயிற்சி பெறுங்கள்.", kn: "ಸಹಜ ಶಬ್ದಕೋಶ ನೆನಪು, ವಾಕ್ಯ ರಚನೆ ಮತ್ತು ಸಂಭಾಷಣಾ ನಿರರ್ಗಳತೆಯನ್ನು ಬಲಪಡಿಸಲು ವಾಸ್ತವಿಕ, ಬಹು-ಸರದಿ ರೋಲ್‌ಪ್ಲೇ ಸಂಭಾಷಣೆಗಳಲ್ಲಿ ತೊಡಗಿಸಿಕೊಳ್ಳಿ. ಸರದಿ-ಸರದಿ ಪ್ರತಿಕ್ರಿಯೆ, ಅಗತ್ಯವಿದ್ದರೆ ಬೆಂಬಲ ಸೂಚನೆಗಳು ಮತ್ತು ನಿಮ್ಮ ಸ್ವಂತ ಮಾತುಗಳಲ್ಲಿ ಪ್ರತಿಕ್ರಿಯಿಸುವ ಅಭ್ಯಾಸ ಪಡೆಯಿರಿ.", bn: "স্বাভাবিক শব্দভাণ্ডার স্মরণ, বাক্য গঠন ও কথোপকথন সাবলীলতা শক্তিশালী করতে বাস্তবসম্মত, বহু-পালা রোলপ্লে কথোপকথনে অংশ নিন। পালা-ভিত্তিক প্রতিক্রিয়া, প্রয়োজনে সহায়ক ইঙ্গিত এবং নিজের ভাষায় উত্তর দেওয়ার অনুশীলন পান।", mr: "नैसर्गिक शब्दसंग्रह स्मरण, वाक्यरचना व संभाषण अस्खलितता बळकट करण्यासाठी वास्तववादी, बहु-वळण रोलप्ले संभाषणांमध्ये सहभागी व्हा. वळणा-वळणाचा अभिप्राय, आवश्यक असल्यास सहाय्यक सूचना व स्वतःच्या शब्दांत उत्तर देण्याचा सराव मिळवा." },
  "roleplay.stat_practice_style": { en: "Practice Style", te: "అభ్యాస శైలి", hi: "अभ्यास शैली", ta: "பயிற்சி பாணி", kn: "ಅಭ್ಯಾಸ ಶೈಲಿ", bn: "অনুশীলন শৈলী", mr: "सराव शैली" },
