  "roleplay.create_custom": { en: "Create Custom Roleplay", te: "అనుకూల రోల్‌ప్లేను సృష్టించండి", hi: "कस्टम रोलप्ले बनाएं", ta: "தனிப்பயன் பாத்திரமேற்பை உருவாக்கு", kn: "ಕಸ್ಟಮ್ ರೋಲ್‌ಪ್ಲೇ ರಚಿಸಿ", bn: "কাস্টম রোলপ্লে তৈরি করুন", mr: "सानुकूल रोलप्ले तयार करा" },
