  "spoken.to_c2_mastery": { en: "to C2 Mastery", te: "C2 నైపుణ్యానికి", hi: "C2 महारत तक", ta: "C2 தேர்ச்சிக்கு", kn: "C2 ಪಾಂಡಿತ್ಯಕ್ಕೆ", bn: "C2 পারদর্শিতা পর্যন্ত", mr: "C2 प्रावीण्यापर्यंत" },
