  "spoken.locked": { en: "Locked", te: "లాక్ చేయబడింది", hi: "लॉक", ta: "பூட்டப்பட்டது", kn: "ಲಾಕ್ ಆಗಿದೆ", bn: "লক করা", mr: "लॉक" },
  "spoken.roadmap_note_prefix": { en: "Course lessons for", te: "కోర్సు పాఠాలు", hi: "पाठ्यक्रम पाठ", ta: "பாட பாடங்கள்", kn: "ಕೋರ್ಸ್ ಪಾಠಗಳು", bn: "কোর্স পাঠ", mr: "कोर्स धडे" },
  "spoken.roadmap_note_suffix": { en: "are unlocked. Complete all Level", te: "అన్‌లాక్ చేయబడ్డాయి. అన్ని స్థాయి", hi: "अनलॉक हैं। सभी स्तर", ta: "திறக்கப்பட்டுள்ளன. அனைத்து நிலை", kn: "ಅನ್‌ಲಾಕ್ ಆಗಿವೆ. ಎಲ್ಲಾ ಹಂತ", bn: "আনলক করা আছে। সমস্ত স্তর", mr: "अनलॉक झाले आहेत. सर्व स्तर" },
  "spoken.roadmap_note_end": { en: "lessons and pass the End-of-Level Assessment with ≥ 80% to unlock the subsequent level on your path to C2!", te: "పాఠాలు మరియు C2కి మీ మార్గంలో తదుపరి స్థాయిని అన్‌లాక్ చేయడానికి ≥ 80%తో ఎండ్-ఆఫ్-లెవల్ అసెస్‌మెంట్‌లో ఉత్తీర్ణులవ్వండి!", hi: "पाठों को पूरा करें और C2 की ओर अपने मार्ग पर अगला स्तर अनलॉक करने के लिए एंड-ऑफ-लेवल मूल्यांकन में ≥ 80% के साथ उत्तीर्ण हों!", ta: "பாடங்களை முடித்து C2 நோக்கிய உங்கள் பாதையில் அடுத்த நிலையைத் திறக்க ≥ 80% உடன் நிலை-முடிவு மதிப்பீட்டில் தேறுங்கள்!", kn: "ಪಾಠಗಳನ್ನು ಪೂರ್ಣಗೊಳಿಸಿ ಮತ್ತು C2 ಕಡೆಗಿನ ನಿಮ್ಮ ಮಾರ್ಗದಲ್ಲಿ ಮುಂದಿನ ಹಂತವನ್ನು ಅನ್‌ಲಾಕ್ ಮಾಡಲು ≥ 80% ಜೊತೆ ಹಂತ-ಅಂತ್ಯ ಮೌಲ್ಯಮಾಪನದಲ್ಲಿ ಉತ್ತೀರ್ಣರಾಗಿ!", bn: "পাঠগুলো সম্পন্ন করুন এবং C2-এর দিকে আপনার পথে পরবর্তী স্তর আনলক করতে ≥ ৮০% নিয়ে স্তর-সমাপ্তি মূল্যায়নে উত্তীর্ণ হন!", mr: "धडे पूर्ण करा आणि C2 कडे तुमच्या मार्गावर पुढील स्तर अनलॉक करण्यासाठी ≥ 80% सह स्तर-समाप्ती मूल्यांकनात उत्तीर्ण व्हा!" },
  "spoken.positive_highlights_title": { en: "What You Did Well (Positive Oral Highlights)", te: "మీరు బాగా చేసినది (సానుకూల మౌఖిక ముఖ్యాంశాలు)", hi: "आपने क्या अच्छा किया (सकारात्मक मौखिक मुख्यांश)", ta: "நீங்கள் நன்றாகச் செய்தது (நேர்மறை வாய்மொழி சிறப்பம்சங்கள்)", kn: "ನೀವು ಚೆನ್ನಾಗಿ ಮಾಡಿದ್ದು (ಸಕಾರಾತ್ಮಕ ಮೌಖಿಕ ಮುಖ್ಯಾಂಶಗಳು)", bn: "আপনি যা ভালো করেছেন (ইতিবাচক মৌখিক হাইলাইট)", mr: "तुम्ही चांगले काय केले (सकारात्मक तोंडी ठळक मुद्दे)" },
