  "spoken.key_corrections_suffix": { en: "key linguistic corrections", te: "ముఖ్య భాషా సవరణలు", hi: "प्रमुख भाषाई सुधार", ta: "முக்கிய மொழியியல் திருத்தங்கள்", kn: "ಪ್ರಮುಖ ಭಾಷಾ ತಿದ್ದುಪಡಿಗಳು", bn: "প্রধান ভাষাগত সংশোধন", mr: "मुख्य भाषिक सुधारणा" },
